INSERT INTO ruleset_versions(id,status,version,season_id,ruleset_id) VALUES('f5eb3609-e7d8-5c53-b9f6-1d7f3e74170a','review',2,'7130abad-a951-40c3-a4c3-e45fd5d3f0ee','2c9589c5-de52-4a88-a50b-77790cce855e');
INSERT INTO rule_categories(id,name,slug,display_order,ruleset_version_id) VALUES('d11c2811-77e0-516c-af5c-383f7ee62629','Pitch / Strike Zone','pitching',10,'f5eb3609-e7d8-5c53-b9f6-1d7f3e74170a');
INSERT INTO rule_categories(id,name,slug,display_order,ruleset_version_id) VALUES('af4cdaff-c758-5180-8409-b84640c6dfce','Fair or Foul','fair-foul',20,'f5eb3609-e7d8-5c53-b9f6-1d7f3e74170a');
INSERT INTO rule_categories(id,name,slug,display_order,ruleset_version_id) VALUES('606c870b-f252-5fa0-b6b2-a85cb319a14c','Base Running','base-running',30,'f5eb3609-e7d8-5c53-b9f6-1d7f3e74170a');
INSERT INTO rule_categories(id,name,slug,display_order,ruleset_version_id) VALUES('932e26ec-ea90-50ea-a47a-60612a8f1f50','Overthrows','overthrows',40,'f5eb3609-e7d8-5c53-b9f6-1d7f3e74170a');
INSERT INTO rule_categories(id,name,slug,display_order,ruleset_version_id) VALUES('97654877-fa3b-5649-86d7-f37ac19d02c1','Fielding','fielding',50,'f5eb3609-e7d8-5c53-b9f6-1d7f3e74170a');
INSERT INTO rule_categories(id,name,slug,display_order,ruleset_version_id) VALUES('dcf17585-c7a9-5d3d-9321-bd1a73c4ab19','Scoring','scoring',60,'f5eb3609-e7d8-5c53-b9f6-1d7f3e74170a');
INSERT INTO rule_categories(id,name,slug,display_order,ruleset_version_id) VALUES('ff1bbfd7-f9be-55e7-b583-f17f31d8af41','Umpire Signals','signals',70,'f5eb3609-e7d8-5c53-b9f6-1d7f3e74170a');
INSERT INTO rules(id,title,rule_key,category_id,official_text,quick_summary,source_section,ruleset_version_id,verification_status) VALUES('1de48c55-1890-582d-957a-d5f60306e6c3','Four Balls','four-balls','d11c2811-77e0-516c-af5c-383f7ee62629','Four balls award first base. A four-pitch intentional walk at the beginning count has the special second-base award described by the league.','4 balls equals a walk; intentional 4-0-0 walk has a special award.','9.1-9.1.1','f5eb3609-e7d8-5c53-b9f6-1d7f3e74170a','verified');
INSERT INTO rules(id,title,rule_key,category_id,official_text,quick_summary,source_section,ruleset_version_id,verification_status) VALUES('16825923-e7ec-5d6f-9ce3-776d734b391c','Three Strikes','three-strikes','d11c2811-77e0-516c-af5c-383f7ee62629','Three strikes retire the kicker. Fouls are tracked separately and are not strikes.','3 strikes equals an out; fouls do not add strikes.','8.1','f5eb3609-e7d8-5c53-b9f6-1d7f3e74170a','verified');
INSERT INTO rules(id,title,rule_key,category_id,official_text,quick_summary,source_section,ruleset_version_id,verification_status) VALUES('46c43590-2974-56c1-8993-4dff259a5c25','Four Fouls','four-fouls','af4cdaff-c758-5180-8409-b84640c6dfce','Four fouls retire the kicker and are counted independently from strikes.','4 fouls equals an out.','10.1','f5eb3609-e7d8-5c53-b9f6-1d7f3e74170a','verified');
INSERT INTO rules(id,title,rule_key,category_id,official_text,quick_summary,source_section,ruleset_version_id,verification_status) VALUES('074a27a9-4915-53c4-81b3-b7f0be2507de','Force Outs','force-outs','606c870b-f252-5fa0-b6b2-a85cb319a14c','The force begins when an uncaught kick lands fair. A defender possessing the ball may retire a forced runner by touching the required base first.','Touch the forced base with possession; no body tag is required.','7.7; 11.2','f5eb3609-e7d8-5c53-b9f6-1d7f3e74170a','verified');
INSERT INTO rules(id,title,rule_key,category_id,official_text,quick_summary,source_section,ruleset_version_id,verification_status) VALUES('a92e7d61-1651-5c74-8e21-eac9c4c8527f','Adjacent Infield','overthrow-adjacent-infield','932e26ec-ea90-50ea-a47a-60612a8f1f50','When the ball enters an adjacent infield, play ends and runners receive the base they were moving toward plus two additional bases.','Dead ball; target base plus two.','12.4','f5eb3609-e7d8-5c53-b9f6-1d7f3e74170a','verified');
INSERT INTO rules(id,title,rule_key,category_id,official_text,quick_summary,source_section,ruleset_version_id,verification_status) VALUES('08e68b10-7e27-5e65-8536-130329de89fb','General Overthrow','overthrow-general','932e26ec-ea90-50ea-a47a-60612a8f1f50','On fields 5 and 6, the general-overthrow limit applies beyond 15 feet outside the foul line, inside the game area and outside unsafe areas. On a throw toward first, the kicker is initially limited to second at risk. A continuing defensive play can permit further advancement.','Play continues; kicker initially capped at second on first-base overthrow.','7.11.3','f5eb3609-e7d8-5c53-b9f6-1d7f3e74170a','verified');
INSERT INTO rules(id,title,rule_key,category_id,official_text,quick_summary,source_section,ruleset_version_id,verification_status) VALUES('94f00f96-5b5c-51a9-8b21-d7c00c2d4612','Dead-Ball Overthrow','overthrow-dead-ball','932e26ec-ea90-50ea-a47a-60612a8f1f50','If an overthrow enters an unsafe or unplayable area inside the designated game area, play ends and runners receive only the base they were on or headed toward.','Dead ball; target base only.','7.11.2','f5eb3609-e7d8-5c53-b9f6-1d7f3e74170a','verified');
INSERT INTO rules(id,title,rule_key,category_id,official_text,quick_summary,source_section,ruleset_version_id,verification_status) VALUES('ed9412eb-420f-5ecf-871b-081ef659a765','Out-of-Bounds Overthrow','overthrow-out-of-bounds','932e26ec-ea90-50ea-a47a-60612a8f1f50','If an overthrow leaves the designated game area, play ends and runners receive the base they were on or headed toward plus one additional base.','Dead ball; target base plus one.','7.11.1','f5eb3609-e7d8-5c53-b9f6-1d7f3e74170a','verified');
INSERT INTO rules(id,title,rule_key,category_id,official_text,quick_summary,source_section,ruleset_version_id,verification_status) VALUES('0d77b6df-647d-5d94-b3c9-9ac70f8b916f','Encroachment','encroachment','97654877-fa3b-5649-86d7-f37ac19d02c1','Restricted fielders remain behind the first-to-third line until the kicker touches the ball.','Fielders cannot cross early.','5.2-5.2.4','f5eb3609-e7d8-5c53-b9f6-1d7f3e74170a','verified');
INSERT INTO rules(id,title,rule_key,category_id,official_text,quick_summary,source_section,ruleset_version_id,verification_status) VALUES('335357f0-77fd-5e9a-be02-00e82b9d0964','Strike Zone and Pitch Strike','strike-zone','d11c2811-77e0-516c-af5c-383f7ee62629','For an un-kicked pitch, check all ball conditions in 9.2 before applying zone overlap. The zone follows home-plate shape, extends one foot on each side, and is one foot high. A missed attempted kick is also a strike.','Any part of the ball entering the strike zone can be a strike; missed kick attempts are strikes, while pitch-shape requirements are evaluated separately.','1.6; 8.2; 9.2','f5eb3609-e7d8-5c53-b9f6-1d7f3e74170a','verified');
INSERT INTO rules(id,title,rule_key,category_id,official_text,quick_summary,source_section,ruleset_version_id,verification_status) VALUES('41380a31-7f62-551c-851a-500c0ddcb2e2','Fair and Foul Ball Location','fair-foul-location','af4cdaff-c758-5180-8409-b84640c6dfce','Apply 10.2 and 10.3 together. Untouched fair-to-foul movement before first/third is foul. A fielder deflection after a fair landing stays fair. An airborne foul-territory ball touched by a player whose feet contact fair ground is fair under 10.3(d). The foul line is fair.','Judge fair/foul from the ball location and first qualifying touch/landing under the league rules; foul lines are fair.','10.2-10.4','f5eb3609-e7d8-5c53-b9f6-1d7f3e74170a','verified');
INSERT INTO rules(id,title,rule_key,category_id,official_text,quick_summary,source_section,ruleset_version_id,verification_status) VALUES('ec68fdd3-7284-5b5b-8dca-8d37b342a209','Tagging Up','tag-up','606c870b-f252-5fa0-b6b2-a85cb319a14c','To tag up, a runner must retouch or remain on the starting base until or after the kicked ball either lands or is first touched within fair territory, or is caught in flight within foul territory. When a fly ball is caught, runners must satisfy this tag-up requirement before advancing at their own risk.','Fair territory: release after the ball lands or is first touched. Foul flight: wait until the ball is caught.','7.9','f5eb3609-e7d8-5c53-b9f6-1d7f3e74170a','verified');
INSERT INTO ruling_scenarios(id,why,title,rule_id,call_type,call_label,what_to_do,category_id,scenario_key,search_terms,what_happened,question_prompt,display_priority,decision_tree_json,ruleset_version_id) VALUES('c48edba9-4cd1-5f58-ac6a-042df855b4ee','Stonewall uses four balls for a walk.','Kicker reached four balls','1de48c55-1890-582d-957a-d5f60306e6c3','base_award','WALK','Award first base unless the special intentional-walk condition applies.','d11c2811-77e0-516c-af5c-383f7ee62629','four-balls-walk',ARRAY['four balls','4 balls','walk','base on balls']::text[],'The kicker has accumulated four balls.',NULL,90,NULL,'f5eb3609-e7d8-5c53-b9f6-1d7f3e74170a');
INSERT INTO ruling_scenarios(id,why,title,rule_id,call_type,call_label,what_to_do,category_id,scenario_key,search_terms,what_happened,question_prompt,display_priority,decision_tree_json,ruleset_version_id) VALUES('fd2de3d3-adc7-5d7a-8b65-c75c73924287','Stonewall has a special intentional-walk award for this exact beginning-count sequence.','Four consecutive balls at 4-0-0','1de48c55-1890-582d-957a-d5f60306e6c3','base_award','AWARD SECOND BASE','Award the kicker second base. Other runners advance only when forced.','d11c2811-77e0-516c-af5c-383f7ee62629','intentional-walk-4-0-0',ARRAY['intentional walk','4-0-0','four straight balls','second base']::text[],'The pitcher throws four consecutive balls from the beginning of the count while clearly avoiding the strike zone.',NULL,95,NULL,'f5eb3609-e7d8-5c53-b9f6-1d7f3e74170a');
INSERT INTO ruling_scenarios(id,why,title,rule_id,call_type,call_label,what_to_do,category_id,scenario_key,search_terms,what_happened,question_prompt,display_priority,decision_tree_json,ruleset_version_id) VALUES('ba8865ca-0ffe-5f84-a7b6-0ad7953a657e','Stonewall uses three strikes for an out and tracks fouls separately.','Kicker reached three strikes','16825923-e7ec-5d6f-9ce3-776d734b391c','out','OUT','Call the kicker out and end the at-bat. Reset the at-bat counts for the next kicker.','d11c2811-77e0-516c-af5c-383f7ee62629','three-strikes-kicker',ARRAY['three strikes','3 strikes','strikeout','strikes']::text[],'The kicker has accumulated three strikes.',NULL,90,NULL,'f5eb3609-e7d8-5c53-b9f6-1d7f3e74170a');
INSERT INTO ruling_scenarios(id,why,title,rule_id,call_type,call_label,what_to_do,category_id,scenario_key,search_terms,what_happened,question_prompt,display_priority,decision_tree_json,ruleset_version_id) VALUES('1eb1ef8b-11d4-5982-9a80-2adb1f567f9d','Fouls are independent from strikes and four fouls retire the kicker.','Kicker reached four fouls','46c43590-2974-56c1-8993-4dff259a5c25','out','OUT','Call the kicker out and reset the at-bat counts for the next kicker.','af4cdaff-c758-5180-8409-b84640c6dfce','four-fouls-kicker',ARRAY['four fouls','4 fouls','foul out','fouls']::text[],'The kicker has accumulated four fouls.',NULL,90,NULL,'f5eb3609-e7d8-5c53-b9f6-1d7f3e74170a');
INSERT INTO ruling_scenarios(id,why,title,rule_id,call_type,call_label,what_to_do,category_id,scenario_key,search_terms,what_happened,question_prompt,display_priority,decision_tree_json,ruleset_version_id) VALUES('a95bd069-276f-5429-b51f-646d0cc2e935','A force is completed by possession plus touching the forced base before the runner.','Defender touched the forced base with possession','074a27a9-4915-53c4-81b3-b7f0be2507de','out','OUT','Call the forced runner out. A body tag is not required.','606c870b-f252-5fa0-b6b2-a85cb319a14c','force-base-touch',ARRAY['force out','touch base','no tag','runner forced']::text[],'An uncaught kick lands fair, forcing a runner forward. A defender with possession touches the forced base before the runner.',NULL,95,NULL,'f5eb3609-e7d8-5c53-b9f6-1d7f3e74170a');
INSERT INTO ruling_scenarios(id,why,title,rule_id,call_type,call_label,what_to_do,category_id,scenario_key,search_terms,what_happened,question_prompt,display_priority,decision_tree_json,ruleset_version_id) VALUES('f5c60e0c-af1f-5877-8d00-38ca505d414f','Adjacent-infield interference uses a separate two-base award.','Ball entered an adjacent infield','a92e7d61-1651-5c74-8e21-eac9c4c8527f','dead_ball','DEAD BALL — AWARD +2','Stop play. Award each runner the base they were moving toward plus two additional bases.','932e26ec-ea90-50ea-a47a-60612a8f1f50','ball-adjacent-infield',ARRAY['adjacent field','adjacent infield','plus two','other field']::text[],'The ball enters the infield of an adjacent field.',NULL,95,NULL,'f5eb3609-e7d8-5c53-b9f6-1d7f3e74170a');
INSERT INTO ruling_scenarios(id,why,title,rule_id,call_type,call_label,what_to_do,category_id,scenario_key,search_terms,what_happened,question_prompt,display_priority,decision_tree_json,ruleset_version_id) VALUES('4e8389f3-978b-5a68-9d9d-ec599e54bf3e','A general overthrow does not automatically end play or guarantee a base.','Playable overthrow past first','08e68b10-7e27-5e65-8536-130329de89fb','live_ball','PLAY CONTINUES','Keep play live. The kicker is initially limited to second at risk; other runners may continue. Further advancement requires a continuing defensive play.','932e26ec-ea90-50ea-a47a-60612a8f1f50','overthrow-past-first',ARRAY['general overthrow','past first','15 feet','play continues','second base']::text[],'Playable overthrow exceeds 15 feet beyond the foul line on field 5 or 6, outside unsafe areas.',NULL,100,NULL,'f5eb3609-e7d8-5c53-b9f6-1d7f3e74170a');
INSERT INTO ruling_scenarios(id,why,title,rule_id,call_type,call_label,what_to_do,category_id,scenario_key,search_terms,what_happened,question_prompt,display_priority,decision_tree_json,ruleset_version_id) VALUES('14f339d3-2774-5e47-80ee-5f02613062df','The dead-ball overthrow award stops at the target base.','Ball entered an unsafe or unplayable area','94f00f96-5b5c-51a9-8b21-d7c00c2d4612','dead_ball','DEAD BALL — TARGET BASE ONLY','Stop play. Place runners at the base they were on or headed toward, with no extra base.','932e26ec-ea90-50ea-a47a-60612a8f1f50','overthrow-unsafe-area',ARRAY['dead ball','unsafe area','unplayable','soccer net','equipment']::text[],'The ball enters an unsafe or unplayable area while still inside the designated game area.',NULL,100,NULL,'f5eb3609-e7d8-5c53-b9f6-1d7f3e74170a');
INSERT INTO ruling_scenarios(id,why,title,rule_id,call_type,call_label,what_to_do,category_id,scenario_key,search_terms,what_happened,question_prompt,display_priority,decision_tree_json,ruleset_version_id) VALUES('5a031de9-a8ab-5070-9106-bc8e97a0112f','This is the out-of-bounds overthrow award.','Ball left the designated game area','ed9412eb-420f-5ecf-871b-081ef659a765','dead_ball','DEAD BALL — AWARD +1','Stop play. Award each runner the base they were on or headed toward plus one additional base.','932e26ec-ea90-50ea-a47a-60612a8f1f50','overthrow-left-game-area',ARRAY['overthrow','out of bounds','left turf','left game area','plus one']::text[],'A thrown ball leaves the designated game area.',NULL,100,NULL,'f5eb3609-e7d8-5c53-b9f6-1d7f3e74170a');
INSERT INTO ruling_scenarios(id,why,title,rule_id,call_type,call_label,what_to_do,category_id,scenario_key,search_terms,what_happened,question_prompt,display_priority,decision_tree_json,ruleset_version_id) VALUES('a54dabde-c019-51a5-8c37-a4c989c450f0','Fielders are restricted until the kick.','Fielder crossed the restriction line early','0d77b6df-647d-5d94-b3c9-9ac70f8b916f','warning_or_award','ENCROACHMENT','First team violation: warn the team; replay only if the defense benefited. Second and later violations: award first regardless of the kick outcome.','97654877-fa3b-5649-86d7-f37ac19d02c1','fielder-crossed-early',ARRAY['encroachment','crossed early','fielder line','before kick','first third line']::text[],'A restricted fielder crosses the first-to-third restriction line before the kicker touches the ball.',NULL,95,NULL,'f5eb3609-e7d8-5c53-b9f6-1d7f3e74170a');
INSERT INTO ruling_scenarios(id,why,title,rule_id,call_type,call_label,what_to_do,category_id,scenario_key,search_terms,what_happened,question_prompt,display_priority,decision_tree_json,ruleset_version_id) VALUES('09a2c8d0-0b48-5508-ab37-e437168273c6','The official rules define fair and foul from the ball location, touch/landing, and whether it has passed first or third base.','Ball near a foul line or changes territory','41380a31-7f62-551c-851a-500c0ddcb2e2','fair_or_foul','FAIR / FOUL — USE LOCATION','Apply 10.2–10.4. Check fair landing followed by fielder deflection, and airborne-ball contact by a player grounded in fair territory, before deciding foul. The line itself is fair.','af4cdaff-c758-5180-8409-b84640c6dfce','fair-foul-location-touch',ARRAY['fair foul','foul line','first touch','lands foul','lands fair','before first','before third','past first','past third','line is fair']::text[],'A kicked ball lands, is touched, or moves near a foul line, including a ball that changes from fair to foul territory.',NULL,100,NULL,'f5eb3609-e7d8-5c53-b9f6-1d7f3e74170a');
INSERT INTO ruling_scenarios(id,why,title,rule_id,call_type,call_label,what_to_do,category_id,scenario_key,search_terms,what_happened,question_prompt,display_priority,decision_tree_json,ruleset_version_id) VALUES('ef928f4f-e5a3-55b8-92b6-c5d12b56be9a','The official rules define the strike zone and state that any part of the ball entering it is enough for a strike; an attempted kick that misses is also a strike.','Pitch reaches the strike zone','335357f0-77fd-5e9a-be02-00e82b9d0964','strike','STRIKE','Check 9.2 first: rolling or at least two ground contacts before home, and permitted height through the kicking box and plate. Then call strike for zone overlap. A missed kick is also a strike.','d11c2811-77e0-516c-af5c-383f7ee62629','pitch-enters-strike-zone',ARRAY['strike zone','edge of zone','one foot','pitch strike','swung and missed','missed kick','bounce','rolling pitch']::text[],'An un-kicked pitch overlaps the zone, after satisfying the pitch requirements.',NULL,100,NULL,'f5eb3609-e7d8-5c53-b9f6-1d7f3e74170a');
INSERT INTO ruling_scenarios(id,why,title,rule_id,call_type,call_label,what_to_do,category_id,scenario_key,search_terms,what_happened,question_prompt,display_priority,decision_tree_json,ruleset_version_id) VALUES('a20b21f9-5c89-589e-bf50-9eda72cd0e48','Rule 7.9 uses different release points: first touch or landing in fair territory, but a completed catch for a foul ball in flight.','Runner left before satisfying tag-up','ec68fdd3-7284-5b5b-8dca-8d37b342a209','out','TAG-UP VIOLATION','For a fair ball, require the runner to remain on or retouch the starting base until the ball lands or is first touched in fair territory. For a ball caught in flight in foul territory, require the runner to remain on or retouch until the catch is completed. Failure to satisfy tag-up on the caught ball is an out.','606c870b-f252-5fa0-b6b2-a85cb319a14c','runner-left-early-fly',ARRAY['tag up','runner left early','caught fly','fair fly','foul fly','first touch','caught foul','retouch']::text[],'A fly is caught; the runner left before the applicable release point and failed to retouch.',NULL,100,NULL,'f5eb3609-e7d8-5c53-b9f6-1d7f3e74170a');
INSERT INTO rule_visuals(id,title,alt_text,visual_key,attribution,scenario_id,visual_type,definition_json,ruleset_version_id) VALUES('b57b0f7a-d802-5404-bc1f-74d4b8939a68','Runner left before satisfying tag-up','Schematic example; follow the three captions and cited rule, not scaled distances.','visual-runner-left-early-fly',NULL,'a20b21f9-5c89-589e-bf50-9eda72cd0e48','stepped','{"field": "kickball_standard", "orientation": "home-at-bottom", "steps": [{"phase": "before", "caption": "Fair-territory example: runner stays on first while the fly has not landed or been touched.", "elements": [{"type": "runner", "x": 75, "y": 65, "label": "R"}, {"type": "fielder", "x": 50, "y": 24, "label": "F"}, {"type": "ball", "x": 50, "y": 14}]}, {"phase": "play", "caption": "Runner departs before first touch. A completed catch follows, and the runner does not retouch.", "elements": [{"type": "path", "from": [75, 65], "to": [50, 40], "kind": "runner"}, {"type": "runner", "x": 63, "y": 53, "label": "R"}, {"type": "fielder", "x": 50, "y": 24, "label": "F"}, {"type": "ball", "x": 52, "y": 22}]}, {"phase": "call", "caption": "On this caught fly, failure to retouch makes the runner out. In foul territory, release requires the completed catch.", "elements": [{"type": "label", "text": "OUT \u2022 NO RETOUCH", "x": 50, "y": 15}, {"type": "runner", "x": 63, "y": 53, "label": "R"}, {"type": "fielder", "x": 50, "y": 24, "label": "F"}, {"type": "ball", "x": 52, "y": 22}]}], "not_to_scale": true}'::jsonb,'f5eb3609-e7d8-5c53-b9f6-1d7f3e74170a');
INSERT INTO rule_visuals(id,title,alt_text,visual_key,attribution,scenario_id,visual_type,definition_json,ruleset_version_id) VALUES('3dbe8c7d-8fbe-5e6c-b0df-3ba0da6ad032','Playable overthrow past first','Schematic example; follow the three captions and cited rule, not scaled distances.','visual-overthrow-past-first',NULL,'4e8389f3-978b-5a68-9d9d-ec599e54bf3e','stepped','{"field": "kickball_standard", "orientation": "home-at-bottom", "steps": [{"phase": "before", "caption": "Fields 5/6 example: defense throws toward first after the kick.", "elements": [{"type": "runner", "x": 65, "y": 74, "label": "K"}, {"type": "fielder", "x": 75, "y": 65, "label": "1B"}, {"type": "ball", "x": 60, "y": 55}]}, {"phase": "play", "caption": "Ball remains playable, more than 15 feet beyond the foul line. Distance is schematic.", "elements": [{"type": "path", "from": [60, 55], "to": [90, 78], "kind": "throw"}, {"type": "ball", "x": 90, "y": 78}, {"type": "runner", "x": 64, "y": 54, "label": "K"}, {"type": "path", "from": [75, 65], "to": [50, 40], "kind": "runner"}]}, {"phase": "call", "caption": "Kicker may reach second at risk. Beyond second requires defense to bring the ball back and continue play.", "elements": [{"type": "label", "text": "LIVE \u2022 AT RISK", "x": 50, "y": 15}, {"type": "runner", "x": 50, "y": 40, "label": "K"}, {"type": "ball", "x": 90, "y": 78}]}], "not_to_scale": true}'::jsonb,'f5eb3609-e7d8-5c53-b9f6-1d7f3e74170a');
INSERT INTO rule_visuals(id,title,alt_text,visual_key,attribution,scenario_id,visual_type,definition_json,ruleset_version_id) VALUES('51d8e53d-c5cc-57d2-a954-60471fa6fd5a','Ball entered an unsafe or unplayable area','Schematic example; follow the three captions and cited rule, not scaled distances.','visual-overthrow-unsafe-area',NULL,'14f339d3-2774-5e47-80ee-5f02613062df','stepped','{"field": "kickball_standard", "orientation": "home-at-bottom", "steps": [{"phase": "before", "caption": "Example: runner leaves first and advances toward second.", "elements": [{"type": "runner", "x": 75, "y": 65, "label": "R"}, {"type": "path", "from": [75, 65], "to": [50, 40], "kind": "runner"}, {"type": "fielder", "x": 60, "y": 58, "label": "F"}, {"type": "ball", "x": 62, "y": 56}]}, {"phase": "play", "caption": "At the instant the ball enters the marked area, the runner is moving toward second.", "elements": [{"type": "zone", "shape": "circle", "x": 88, "y": 58, "radius": 8, "label": "UNSAFE AREA"}, {"type": "path", "from": [62, 56], "to": [88, 58], "kind": "throw"}, {"type": "ball", "x": 88, "y": 58}, {"type": "runner", "x": 63, "y": 53, "label": "R"}, {"type": "path", "from": [63, 53], "to": [50, 40], "kind": "runner"}]}, {"phase": "call", "caption": "Dead ball inside unsafe area: this runner goes to second, with no extra base.", "elements": [{"type": "label", "text": "DEAD BALL", "x": 50, "y": 15}, {"type": "path", "from": [63, 53], "to": [50, 40], "kind": "runner"}, {"type": "runner", "x": 50, "y": 40, "label": "R"}]}], "not_to_scale": true}'::jsonb,'f5eb3609-e7d8-5c53-b9f6-1d7f3e74170a');
INSERT INTO rule_visuals(id,title,alt_text,visual_key,attribution,scenario_id,visual_type,definition_json,ruleset_version_id) VALUES('85d36d4a-3bb7-59e4-a0e7-12398593a0ed','Ball left the designated game area','Schematic example; follow the three captions and cited rule, not scaled distances.','visual-overthrow-left-game-area',NULL,'5a031de9-a8ab-5070-9106-bc8e97a0112f','stepped','{"field": "kickball_standard", "orientation": "home-at-bottom", "steps": [{"phase": "before", "caption": "Example: runner leaves first and advances toward second.", "elements": [{"type": "runner", "x": 75, "y": 65, "label": "R"}, {"type": "path", "from": [75, 65], "to": [50, 40], "kind": "runner"}, {"type": "fielder", "x": 60, "y": 58, "label": "F"}, {"type": "ball", "x": 62, "y": 56}]}, {"phase": "play", "caption": "At the instant the ball enters the marked area, the runner is moving toward second.", "elements": [{"type": "zone", "shape": "edge", "side": "right", "label": "GAME BOUNDARY"}, {"type": "path", "from": [62, 56], "to": [98, 42], "kind": "throw"}, {"type": "ball", "x": 98, "y": 42}, {"type": "runner", "x": 63, "y": 53, "label": "R"}, {"type": "path", "from": [63, 53], "to": [50, 40], "kind": "runner"}]}, {"phase": "call", "caption": "Out-of-bounds overthrow: this runner gets second plus one base, ending at third.", "elements": [{"type": "label", "text": "DEAD BALL", "x": 50, "y": 15}, {"type": "path", "from": [63, 53], "to": [50, 40], "kind": "runner"}, {"type": "path", "from": [50, 40], "to": [25, 65], "kind": "runner"}, {"type": "runner", "x": 25, "y": 65, "label": "R"}]}], "not_to_scale": true}'::jsonb,'f5eb3609-e7d8-5c53-b9f6-1d7f3e74170a');
INSERT INTO rule_visuals(id,title,alt_text,visual_key,attribution,scenario_id,visual_type,definition_json,ruleset_version_id) VALUES('6cd038c3-2d98-5fc2-8315-5d337b46f0ba','Defender touched the forced base with possession','Schematic example; follow the three captions and cited rule, not scaled distances.','visual-force-base-touch',NULL,'a95bd069-276f-5429-b51f-646d0cc2e935','stepped','{"field": "kickball_standard", "orientation": "home-at-bottom", "steps": [{"phase": "before", "caption": "A kicked ball lands fair without being caught. Runner on first is forced toward second.", "elements": [{"type": "ball", "x": 42, "y": 55}, {"type": "runner", "x": 75, "y": 65, "label": "R"}, {"type": "runner", "x": 58, "y": 81, "label": "K"}, {"type": "fielder", "x": 50, "y": 40, "label": "F"}]}, {"phase": "play", "caption": "Defender touches second with possession before the forced runner reaches it.", "elements": [{"type": "path", "from": [75, 65], "to": [50, 40], "kind": "runner"}, {"type": "runner", "x": 60, "y": 50, "label": "R"}, {"type": "fielder", "x": 50, "y": 40, "label": "F"}, {"type": "ball", "x": 52, "y": 38}]}, {"phase": "call", "caption": "The forced runner is out; no body tag is needed.", "elements": [{"type": "label", "text": "FORCE OUT", "x": 50, "y": 15}, {"type": "fielder", "x": 50, "y": 40, "label": "F"}, {"type": "ball", "x": 52, "y": 38}, {"type": "runner", "x": 60, "y": 50, "label": "R"}]}], "not_to_scale": true}'::jsonb,'f5eb3609-e7d8-5c53-b9f6-1d7f3e74170a');
INSERT INTO rule_visuals(id,title,alt_text,visual_key,attribution,scenario_id,visual_type,definition_json,ruleset_version_id) VALUES('b7e162da-ccfd-51b0-8d61-88ed7c8bbf32','Ball entered an adjacent infield','Schematic example; follow the three captions and cited rule, not scaled distances.','visual-ball-adjacent-infield',NULL,'f5c60e0c-af1f-5877-8d00-38ca505d414f','stepped','{"field": "kickball_standard", "orientation": "home-at-bottom", "steps": [{"phase": "before", "caption": "Example: runner leaves first and advances toward second.", "elements": [{"type": "runner", "x": 75, "y": 65, "label": "R"}, {"type": "path", "from": [75, 65], "to": [50, 40], "kind": "runner"}, {"type": "fielder", "x": 60, "y": 58, "label": "F"}, {"type": "ball", "x": 62, "y": 56}]}, {"phase": "play", "caption": "At the instant the ball enters the marked area, the runner is moving toward second.", "elements": [{"type": "zone", "shape": "rect", "x": 84, "y": 20, "width": 16, "height": 28, "label": "ADJACENT INFIELD"}, {"type": "path", "from": [62, 56], "to": [95, 32], "kind": "throw"}, {"type": "ball", "x": 95, "y": 32}, {"type": "runner", "x": 63, "y": 53, "label": "R"}, {"type": "path", "from": [63, 53], "to": [50, 40], "kind": "runner"}]}, {"phase": "call", "caption": "Adjacent infield: this runner gets second plus two bases, ending at home.", "elements": [{"type": "label", "text": "DEAD BALL", "x": 50, "y": 15}, {"type": "path", "from": [63, 53], "to": [50, 40], "kind": "runner"}, {"type": "path", "from": [50, 40], "to": [25, 65], "kind": "runner"}, {"type": "path", "from": [25, 65], "to": [50, 88], "kind": "runner"}, {"type": "runner", "x": 50, "y": 88, "label": "R"}]}], "not_to_scale": true}'::jsonb,'f5eb3609-e7d8-5c53-b9f6-1d7f3e74170a');
INSERT INTO rule_visuals(id,title,alt_text,visual_key,attribution,scenario_id,visual_type,definition_json,ruleset_version_id) VALUES('a9cddebf-ba26-50c8-a113-4fa54a3139f0','Fielder crossed the restriction line early','Schematic example; follow the three captions and cited rule, not scaled distances.','visual-fielder-crossed-early',NULL,'a54dabde-c019-51a5-8c37-a4c989c450f0','stepped','{"field": "kickball_standard", "orientation": "home-at-bottom", "steps": [{"phase": "before", "caption": "Example: a non-catcher fielder stays behind the first-to-third line before contact.", "elements": [{"type": "zone", "shape": "line", "from": [25, 65], "to": [75, 65], "label": "1B\u20133B LINE"}, {"type": "fielder", "x": 38, "y": 54, "label": "F"}, {"type": "runner", "x": 50, "y": 88, "label": "K"}, {"type": "ball", "x": 50, "y": 75}]}, {"phase": "play", "caption": "Fielder crosses the line while the pitch is still approaching the kicker.", "elements": [{"type": "zone", "shape": "line", "from": [25, 65], "to": [75, 65], "label": "1B\u20133B LINE"}, {"type": "path", "from": [38, 54], "to": [38, 73], "kind": "fielder"}, {"type": "fielder", "x": 38, "y": 73, "label": "F"}, {"type": "runner", "x": 50, "y": 88, "label": "K"}, {"type": "ball", "x": 50, "y": 80}]}, {"phase": "call", "caption": "First team infraction: warning, with a do-over if defense benefited. Later infractions: award first.", "elements": [{"type": "label", "text": "ENCROACHMENT", "x": 50, "y": 15}, {"type": "zone", "shape": "line", "from": [25, 65], "to": [75, 65], "label": "1B\u20133B LINE"}, {"type": "fielder", "x": 38, "y": 73, "label": "F"}]}], "not_to_scale": true}'::jsonb,'f5eb3609-e7d8-5c53-b9f6-1d7f3e74170a');
INSERT INTO rule_visuals(id,title,alt_text,visual_key,attribution,scenario_id,visual_type,definition_json,ruleset_version_id) VALUES('e20fa14f-4070-5e34-9476-fbf3dca47b83','Ball near a foul line or changes territory','Schematic example; follow the three captions and cited rule, not scaled distances.','visual-fair-foul-location-touch',NULL,'09a2c8d0-0b48-5508-ab37-e437168273c6','stepped','{"field": "kickball_standard", "orientation": "home-at-bottom", "steps": [{"phase": "before", "caption": "Example: an untouched kicked ball lands fair before first base.", "elements": [{"type": "ball", "x": 60, "y": 73}, {"type": "label", "text": "UNTOUCHED BALL", "x": 50, "y": 15}]}, {"phase": "play", "caption": "The grounded ball crosses into foul territory on its own before reaching first.", "elements": [{"type": "path", "from": [60, 73], "to": [76, 81], "kind": "ball"}, {"type": "ball", "x": 76, "y": 81}]}, {"phase": "call", "caption": "Foul in this example. Foul lines are fair; fielder-touch cases have separate rules in 10.3.", "elements": [{"type": "label", "text": "FOUL", "x": 50, "y": 15}, {"type": "ball", "x": 76, "y": 81}]}], "not_to_scale": true}'::jsonb,'f5eb3609-e7d8-5c53-b9f6-1d7f3e74170a');
INSERT INTO rule_visuals(id,title,alt_text,visual_key,attribution,scenario_id,visual_type,definition_json,ruleset_version_id) VALUES('2c57e107-66d4-538f-99fb-d538110ea1e2','Pitch reaches the strike zone','Schematic example; follow the three captions and cited rule, not scaled distances.','visual-pitch-enters-strike-zone',NULL,'ef928f4f-e5a3-55b8-92b6-c5d12b56be9a','stepped','{"field": "strike_zone_front", "orientation": "home-at-bottom", "steps": [{"phase": "before", "caption": "Front elevation: one-foot-high zone, with one foot added on each side of the plate. Depth follows the plate.", "elements": [{"type": "label", "text": "FRONT VIEW", "x": 50, "y": 15}, {"type": "ball", "x": 80, "y": 50}]}, {"phase": "play", "caption": "Example assumes a legal rolling/two-bounce pitch and no excessive height in the kicking box.", "elements": [{"type": "label", "text": "LEGAL PITCH", "x": 50, "y": 15}, {"type": "ball", "x": 69, "y": 56}]}, {"phase": "call", "caption": "An un-kicked legal pitch overlapping the zone is a strike. Check Rule 9.2 before calling it.", "elements": [{"type": "label", "text": "STRIKE", "x": 50, "y": 15}, {"type": "ball", "x": 69, "y": 56}]}], "not_to_scale": true}'::jsonb,'f5eb3609-e7d8-5c53-b9f6-1d7f3e74170a');
