INSERT INTO rule_sources(id,url,name,citation,publisher,verified_at,verified_by,ruleset_version_id,verification_status) VALUES('9e928696-40a5-57c2-af89-a62cbf2d6699','https://docs.google.com/document/u/1/d/e/2PACX-1vQ9OBOHo_OxrX3U46sTHYxStc21qJearXIKuRpZ-FuEWlCXSyCg3nqs5co3zdjUKeVQ_7oELo7-nuKH/pub?pli=1','SSB Kickball Rules - Updated 3/17/26','Official Stonewall Sports Boston kickball rules updated 3/17/26','Stonewall Sports Boston','2026-09-11T21:12:38.156283+00:00',NULL,'f5eb3609-e7d8-5c53-b9f6-1d7f3e74170a','verified');
INSERT INTO rule_sources(id,url,name,citation,publisher,verified_at,verified_by,ruleset_version_id,verification_status) VALUES('a5b125f7-e11c-53d0-a0d5-a2e093ed8b9c','https://drive.google.com/file/d/1r2O8EWHLNMwtCj0nzxbB7CVrTUMyggoO/view?usp=drivesdk','Stonewall Boston Fall 2026 Umpire Training','League umpire training video summary supplied for Fall 2026','Stonewall Sports Boston',NULL,NULL,'f5eb3609-e7d8-5c53-b9f6-1d7f3e74170a','review');
INSERT INTO rule_sources(id,url,name,citation,publisher,verified_at,verified_by,ruleset_version_id,verification_status) VALUES('68b6ad44-958f-52a5-822a-8f5816492df8','https://drive.google.com/file/d/1L9KTT58ZPBS0crAA8qpNakbf33KbwneX/view?usp=drivesdk','Stonewall Boston Umpire Call Signs','Stonewall Boston umpire signal reference','Stonewall Sports Boston','2026-09-11T21:12:38.222357+00:00',NULL,'f5eb3609-e7d8-5c53-b9f6-1d7f3e74170a','verified');
INSERT INTO umpire_signals(id,title,rule_id,use_when,source_id,signal_key,verbal_call,instructions,visual_steps,ruleset_version_id) VALUES('d430812f-57e7-5b0d-aac6-53ab520d31b7','Ball',NULL,'When a pitched ball is called “ball”.','68b6ad44-958f-52a5-822a-8f5816492df8','ball','','Cross your thumb in front of your palm or make a ball shape with your hands.','[{"step": 1, "action": "Cross your thumb in front of your palm"}, {"step": 2, "action": "Or make a ball shape with your hands"}]'::jsonb,'f5eb3609-e7d8-5c53-b9f6-1d7f3e74170a');
INSERT INTO umpire_signals(id,title,rule_id,use_when,source_id,signal_key,verbal_call,instructions,visual_steps,ruleset_version_id) VALUES('e8d1f447-1716-529c-a5da-6c7aadd33c68','Strike',NULL,'When a pitched ball is called “strike”.','68b6ad44-958f-52a5-822a-8f5816492df8','strike','','Make a closed fist in front of you as if knocking on a door.','[{"step": 1, "action": "Make a closed fist"}, {"step": 2, "action": "Hold it in front of you as if knocking on a door"}]'::jsonb,'f5eb3609-e7d8-5c53-b9f6-1d7f3e74170a');
INSERT INTO umpire_signals(id,title,rule_id,use_when,source_id,signal_key,verbal_call,instructions,visual_steps,ruleset_version_id) VALUES('ccff7d1d-a68d-55a8-a532-1057ee7d3921','Foul',NULL,'When a ball is called “foul”.','68b6ad44-958f-52a5-822a-8f5816492df8','foul','','Raise a closed fist above your head.','[{"step": 1, "action": "Make a closed fist"}, {"step": 2, "action": "Raise the closed fist above your head"}]'::jsonb,'f5eb3609-e7d8-5c53-b9f6-1d7f3e74170a');
INSERT INTO umpire_signals(id,title,rule_id,use_when,source_id,signal_key,verbal_call,instructions,visual_steps,ruleset_version_id) VALUES('ab7a97b9-8155-514d-8811-968dcdb5f88c','Fair',NULL,'When a ball is called “fair”.','68b6ad44-958f-52a5-822a-8f5816492df8','fair','','Extend your arm out to the side at shoulder height with your palm down. Point your hand towards fair territory.','[{"step": 1, "action": "Extend your arm to the side at shoulder height with palm down"}, {"step": 2, "action": "Point your hand toward fair territory"}]'::jsonb,'f5eb3609-e7d8-5c53-b9f6-1d7f3e74170a');
INSERT INTO umpire_signals(id,title,rule_id,use_when,source_id,signal_key,verbal_call,instructions,visual_steps,ruleset_version_id) VALUES('eaac9d57-6058-5486-b0ad-ddbb23e5454d','Out',NULL,'When a player is called “out”.','68b6ad44-958f-52a5-822a-8f5816492df8','out','','Make a closed fist in front of you as if knocking on a door.','[{"step": 1, "action": "Make a closed fist"}, {"step": 2, "action": "Hold it in front of you as if knocking on a door"}]'::jsonb,'f5eb3609-e7d8-5c53-b9f6-1d7f3e74170a');
INSERT INTO umpire_signals(id,title,rule_id,use_when,source_id,signal_key,verbal_call,instructions,visual_steps,ruleset_version_id) VALUES('6f8feedf-8592-5916-94bf-8ee0dc2988ed','Safe',NULL,'When a player is called “safe”.','68b6ad44-958f-52a5-822a-8f5816492df8','safe','','Sweep your arms out to your sides at shoulder height with palms down.','[{"step": 1, "action": "Raise both arms to shoulder height"}, {"step": 2, "action": "Sweep your arms out to your sides with palms down"}]'::jsonb,'f5eb3609-e7d8-5c53-b9f6-1d7f3e74170a');
INSERT INTO umpire_signals(id,title,rule_id,use_when,source_id,signal_key,verbal_call,instructions,visual_steps,ruleset_version_id) VALUES('e2f2a15d-ecee-50d6-872c-bfbf47c45667','Dead Ball / Play Ends',NULL,'When calling a time out, a ball goes out of bounds or becomes a dead ball, or the play otherwise suddenly ends.','68b6ad44-958f-52a5-822a-8f5816492df8','dead-ball-play-ends','','Raise both open hands above your head. Walk into the field of play.','[{"step": 1, "action": "Raise both open hands above your head"}, {"step": 2, "action": "Walk into the field of play"}]'::jsonb,'f5eb3609-e7d8-5c53-b9f6-1d7f3e74170a');
